<template><view class="page"><view class="head"><text class="eyebrow">校园与企业</text><text class="title">活动广场</text><text class="subtitle">参加你所在学校的低碳活动</text></view><view v-if="schoolName" class="school-tip">当前学校：{{schoolName}}</view><view class="tabs"><text v-for="tab in tabs" :key="tab.key" :class="{selected:current===tab.key}" @tap="current=tab.key">{{tab.label}}</text></view><view v-if="filtered.length" class="activity-list"><view v-for="item in filtered" :key="item._id||item.id" class="activity-card card" @tap="open(item)"><view class="row"><view><text class="activity-title">{{item.title}}</text><text class="muted">{{sourceText(item.organizerType)}} · {{item.date||item.startAt||'未设置日期'}}</text></view><text class="tag">{{activityStatus(item)}}</text></view><text class="activity-desc">{{item.desc||'参与低碳活动，完成后上传凭证申请积分。'}}</text><view class="row meta"><text>地点：{{item.location||'未设置'}}</text><text v-if="item.endAt">截止：{{item.endAt}}</text></view><view class="primary-btn small-btn">查看详情</view></view></view><view v-else class="empty card">{{schoolId?'暂无符合条件的活动':'请先在个人中心绑定学校'}}</view><BottomNav active="activity"/></view></template>
<script>import BottomNav from '../../components/BottomNav.vue';import {callCloud} from '../../common/cloud.js';export default{components:{BottomNav},data(){return{list:[],schoolId:'',schoolName:'',current:'all',tabs:[{key:'all',label:'全部活动'},{key:'ongoing',label:'正在进行'},{key:'completed',label:'已完成'}]}},computed:{filtered(){const states=uni.getStorageSync('activity_submission_status')||{};return this.list.filter(item=>{const status=states[item._id||item.id]||'not_joined';if(this.current==='ongoing')return status==='pending_review'||status==='rejected';if(this.current==='completed')return status==='approved';return true})}},async onShow(){this.schoolId=uni.getStorageSync('user_school_id')||'';this.schoolName=uni.getStorageSync('user_school_name')||'';if(!this.schoolId){this.list=[];return}try{const result=await callCloud('activity-list',{schoolId:this.schoolId});this.list=result.data||[]}catch(error){this.list=[]}},methods:{sourceText(type){return type==='enterprise'?'企业合作':'校园官方'},activityStatus(item){const status=(uni.getStorageSync('activity_submission_status')||{})[item._id||item.id]||'not_joined';return status==='approved'?'已完成':status==='pending_review'?'凭证待审核':status==='rejected'?'已驳回':'未参与'},open(item){uni.navigateTo({url:'/pages/personal/activity-detail?id='+(item._id||item.id)})}}}</script>
<style lang="scss">@import '../../common/portal.scss';.school-tip{margin-bottom:18rpx;color:#347c55;font-size:23rpx}.tabs{display:flex;gap:14rpx;margin:20rpx 0}.tabs text{padding:15rpx 22rpx;border-radius:30rpx;background:#e4e9e6;color:#53615f;font-size:22rpx}.tabs .selected{background:#006d37;color:#fff}.activity-card{margin-bottom:18rpx;padding:24rpx}.activity-title{display:block;font-size:28rpx;font-weight:700}.activity-desc{display:block;margin-top:16rpx;color:#53615f;font-size:23rpx;line-height:1.5}.meta{margin-top:16rpx;color:#6d7a6e;font-size:20rpx}.small-btn{min-height:60rpx;margin-top:18rpx;font-size:22rpx}.empty{text-align:center;color:#89958e}</style>
